/**
 * Deep Cut prompt bank.
 *
 * Each prompt is a tuple: [id, question, peopleFlag, answers]
 *   - id: unique within its category (the full id is "category:id")
 *   - peopleFlag: 1 when answers are people, so a unique surname also matches ("Jokic")
 *   - answers: "Display/alias/alias=share|..." where share is the estimated % of players
 *     who would give that answer. No "=share" means 0.4 (a long-tail answer). "=0" means
 *     "known but not accepted" and is skipped.
 *
 * To add a prompt, add a line to a category. To add a category, add a key here and an
 * entry to CATEGORIES in ../logic.ts.
 */
export type PromptTuple = [id: string, question: string, people: 0 | 1, answers: string];

